/* Fault code library: meanings, causes, fixes and driving advice.
   To add a code: D(code, title, system, severity 1-3, meaning, [causes], [fixes], optional driving advice).
   Severity: 3 = critical, 2 = repair soon, 1 = low priority. Causes are listed most likely first. */

export const DB = {};
function D(code, title, sys, sev, mean, causes, fixes, drive){ DB[code] = {code, title, sys, sev, mean, causes, fixes, drive: drive || null}; }

export const SYS = {fuel:'Fuel & air metering', ign:'Ignition & misfire', emis:'Emissions control', idle:'Speed, idle & electrical', ecm:'Engine computer & outputs', trans:'Transmission', net:'Network communication', chas:'Chassis / ABS', body:'Body / restraints', cam:'Engine timing'};

D('P0010','Intake camshaft position actuator circuit (Bank 1)',SYS.cam,2,'The engine computer cannot properly control the variable valve timing (VVT) solenoid for the intake camshaft. The fault is electrical: the circuit is open, shorted or out of range.',['Faulty VVT / oil control solenoid','Damaged wiring or corroded connector at the solenoid','Blown fuse feeding the solenoid','Engine computer driver fault (rare)'],['Inspect the solenoid connector and wiring for damage or oil contamination','Measure solenoid resistance (typically 6–13 Ω) and compare with spec','Check the fuse and supply voltage','Replace the solenoid if resistance is out of spec']);
D('P0011','Intake camshaft timing over-advanced or system performance (Bank 1)',SYS.cam,2,'The intake camshaft is more advanced than the engine computer is commanding. The VVT system is not responding correctly.',['Low or dirty engine oil','Sticking VVT oil control solenoid','Clogged solenoid screen / oil passage','Worn or stretched timing chain','Faulty VVT phaser (cam gear)'],['Check oil level and condition; change oil and filter with the correct grade','Remove and clean or replace the oil control solenoid','Check cam/crank correlation with a scope or live data','Inspect timing chain, tensioner and phaser if the code returns']);
D('P0012','Intake camshaft timing over-retarded (Bank 1)',SYS.cam,2,'The intake camshaft is more retarded than commanded, so valve timing is late.',['Low or wrong-grade engine oil','VVT solenoid stuck','Timing chain stretched or jumped a tooth','VVT phaser stuck'],['Check oil level and grade, then service the oil','Test and replace the oil control solenoid','Verify mechanical timing marks','Replace phaser or timing components as needed']);
D('P0013','Exhaust camshaft position actuator circuit (Bank 1)',SYS.cam,2,'Electrical fault in the exhaust camshaft VVT solenoid circuit.',['Faulty exhaust VVT solenoid','Wiring or connector damage','Fuse or supply fault'],['Inspect wiring and connector','Test solenoid resistance','Replace solenoid if out of spec']);
D('P0014','Exhaust camshaft timing over-advanced (Bank 1)',SYS.cam,2,'The exhaust camshaft position differs from what the computer commands.',['Low or dirty oil','Sticking exhaust VVT solenoid','Worn timing chain','Faulty phaser'],['Service the oil and filter','Clean or replace the solenoid','Check timing chain stretch']);
D('P0016','Crankshaft / camshaft position correlation (Bank 1 sensor A)',SYS.cam,3,'The crank and cam sensor signals do not line up as expected. This often means the timing chain or belt has stretched or jumped.',['Stretched timing chain or worn guides','Timing belt jumped a tooth','Faulty cam or crank sensor','Damaged reluctor (tone) ring','VVT phaser fault'],['Check cam/crank correlation values in live data','Inspect timing marks and chain/belt condition','Test both position sensors','Replace timing components if worn'],'Do not drive far. A jumped timing belt or chain can let valves hit pistons and destroy the engine.');
D('P0030','O2 sensor heater control circuit (Bank 1 sensor 1)',SYS.emis,1,'The heater inside the upstream oxygen sensor is not working, so the sensor takes longer to reach operating temperature.',['Burnt-out O2 sensor heater element','Blown heater fuse','Wiring damaged near the exhaust'],['Check the O2 heater fuse','Measure heater resistance (usually 2–14 Ω)','Replace the oxygen sensor if the heater is open']);
D('P0036','O2 sensor heater control circuit (Bank 1 sensor 2)',SYS.emis,1,'The heater in the downstream (after catalytic converter) oxygen sensor is faulty.',['Failed sensor heater','Blown fuse','Damaged wiring'],['Check fuse and wiring','Measure heater resistance','Replace the downstream O2 sensor']);
D('P0068','MAP / MAF to throttle position correlation',SYS.fuel,2,'The airflow measured does not match what is expected for the throttle opening. Usually an air leak or a dirty sensor.',['Vacuum leak after the throttle body','Dirty or faulty MAF sensor','Dirty throttle body','Faulty MAP sensor'],['Smoke-test the intake for leaks','Clean the MAF sensor and throttle body','Compare MAF and MAP live data with specification']);
D('P0087','Fuel rail / system pressure too low',SYS.fuel,3,'Fuel pressure in the rail is below what the computer commands. The engine may hesitate, lose power or stall.',['Clogged fuel filter','Weak fuel pump (in-tank or high-pressure)','Faulty fuel pressure regulator','Restricted fuel line or pickup','Faulty rail pressure sensor','Running very low on fuel'],['Make sure the tank has fuel','Replace the fuel filter if serviceable','Measure actual fuel pressure with a gauge and compare with spec','Test pump current and pressure sensor reading'],'Avoid heavy load and overtaking. Low fuel pressure can cause sudden power loss and lean running.');
D('P0088','Fuel rail / system pressure too high',SYS.fuel,2,'Fuel rail pressure is higher than commanded.',['Faulty pressure regulator or relief valve','Faulty rail pressure sensor','Fuel return line restricted'],['Check the pressure sensor reading against a mechanical gauge','Inspect the return line','Test or replace the pressure regulator']);
D('P0100','Mass air flow (MAF) circuit',SYS.fuel,2,'The MAF sensor signal is missing or invalid. The computer will estimate airflow, which affects fuel mixture.',['Unplugged or damaged MAF connector','Faulty MAF sensor','Broken wiring','Blown fuse'],['Check the connector and wiring','Check sensor power and ground','Replace the MAF sensor if the signal is absent with good wiring']);
D('P0101','Mass air flow (MAF) circuit range / performance',SYS.fuel,2,'The MAF reading does not make sense for the engine speed and load.',['Dirty MAF sensor element','Air leak between MAF and throttle body','Clogged air filter','Faulty MAF sensor'],['Replace the air filter if dirty','Clean the MAF with dedicated MAF cleaner (no touching the element)','Check the intake ducting for cracks','Compare MAF g/s at idle with spec (often 2–7 g/s on small petrol engines)']);
D('P0102','Mass air flow (MAF) circuit low input',SYS.fuel,2,'The MAF signal voltage is lower than expected.',['Dirty or failed MAF','Open circuit or poor ground','Large air leak after the MAF'],['Clean and test the MAF','Check wiring and ground','Inspect intake ducting']);
D('P0103','Mass air flow (MAF) circuit high input',SYS.fuel,2,'The MAF signal voltage is higher than expected.',['Faulty MAF sensor','Signal wire shorted to voltage','Electrical interference from nearby wiring'],['Inspect wiring for shorts','Test the sensor','Replace MAF if faulty']);
D('P0106','Manifold absolute pressure (MAP) range / performance',SYS.fuel,2,'The MAP sensor reading does not match the engine conditions.',['Vacuum leak','Cracked or blocked MAP vacuum hose','Faulty MAP sensor'],['Check the MAP hose and intake for leaks','Compare MAP (key on, engine off) to barometric pressure — about 83 kPa in Johannesburg','Replace the MAP sensor if readings are wrong']);
D('P0107','MAP sensor circuit low',SYS.fuel,2,'The MAP sensor voltage is too low.',['Unplugged sensor','Open signal or 5 V reference wire','Faulty sensor'],['Check connector and 5 V reference','Repair wiring','Replace sensor']);
D('P0108','MAP sensor circuit high',SYS.fuel,2,'The MAP sensor voltage is too high.',['Signal shorted to voltage','Bad sensor ground','Faulty sensor'],['Check ground and wiring','Replace sensor']);
D('P0110','Intake air temperature (IAT) sensor circuit',SYS.fuel,1,'The IAT sensor signal is missing or invalid.',['Faulty IAT sensor (often built into the MAF)','Wiring or connector fault'],['Check the connector','Compare the IAT reading to outside temperature on a cold engine','Replace the sensor']);
D('P0112','Intake air temperature sensor circuit low',SYS.fuel,1,'The IAT sensor reads extremely hot, which usually means a short to ground.',['Shorted sensor','Signal wire shorted to ground'],['Inspect wiring','Replace sensor']);
D('P0113','Intake air temperature sensor circuit high',SYS.fuel,1,'The IAT sensor reads extremely cold (around −40 °C), which usually means an open circuit.',['Unplugged sensor','Open wire','Failed sensor'],['Check the connector is fully seated','Test wiring continuity','Replace sensor']);
D('P0115','Engine coolant temperature (ECT) sensor circuit',SYS.fuel,2,'The coolant temperature sensor signal is invalid. Fans, fuelling and the temperature gauge may be affected.',['Faulty ECT sensor','Wiring or connector fault'],['Check connector and wiring','Compare ECT to IAT on a cold engine (should be within a few °C)','Replace the sensor']);
D('P0116','Engine coolant temperature sensor range / performance',SYS.fuel,2,'The coolant temperature reading does not behave as expected as the engine warms.',['Thermostat stuck open','Faulty ECT sensor','Low coolant'],['Check coolant level','Watch ECT warm-up in live data','Replace thermostat or sensor']);
D('P0117','Engine coolant temperature sensor circuit low',SYS.fuel,2,'The ECT sensor reads extremely hot, usually a short to ground.',['Shorted sensor','Shorted signal wire'],['Inspect wiring','Replace sensor']);
D('P0118','Engine coolant temperature sensor circuit high',SYS.fuel,2,'The ECT sensor reads extremely cold, usually an open circuit. The cooling fan may run constantly as a safety measure.',['Unplugged or failed sensor','Open wiring','Corroded connector'],['Check the connector','Test continuity','Replace sensor']);
D('P0120','Throttle position sensor A circuit',SYS.fuel,2,'The throttle position signal is invalid. The car may go into limp mode with reduced power.',['Faulty throttle position sensor','Wiring or connector fault','Faulty electronic throttle body'],['Inspect the throttle body connector','Check the 5 V reference and signal sweep','Replace the sensor or throttle body']);
D('P0121','Throttle position sensor A range / performance',SYS.fuel,2,'The throttle position reading does not match the airflow or the second sensor.',['Worn throttle position sensor','Dirty throttle body','Poor connection'],['Clean the throttle body','Check for a smooth signal sweep with no dropouts','Replace sensor or throttle body']);
D('P0122','Throttle position sensor A circuit low',SYS.fuel,2,'The TPS signal voltage is too low.',['Open 5 V reference or signal','Faulty sensor'],['Check wiring and connector','Replace sensor']);
D('P0123','Throttle position sensor A circuit high',SYS.fuel,2,'The TPS signal voltage is too high.',['Signal shorted to voltage','Open ground','Faulty sensor'],['Check ground and wiring','Replace sensor']);
D('P0125','Insufficient coolant temperature for closed-loop fuel control',SYS.fuel,1,'The engine takes too long to warm up enough for normal fuel control.',['Thermostat stuck open','Faulty ECT sensor','Low coolant'],['Check coolant level','Replace the thermostat if warm-up is slow','Test the ECT sensor']);
D('P0128','Coolant thermostat (coolant temperature below regulating temperature)',SYS.fuel,1,'The engine is not reaching normal operating temperature in the expected time. Almost always a thermostat stuck open.',['Thermostat stuck open','Faulty ECT sensor','Cooling fan running constantly','Low coolant'],['Replace the thermostat and refill/bleed the coolant','Check the fan is not running on a cold engine','Verify ECT reading with a thermometer']);
D('P0130','O2 sensor circuit (Bank 1 sensor 1)',SYS.emis,2,'The upstream oxygen sensor signal is faulty.',['Failed O2 sensor','Wiring damage near the exhaust','Exhaust leak before the sensor'],['Inspect the sensor wiring','Check for exhaust leaks','Replace the sensor']);
D('P0131','O2 sensor circuit low voltage (Bank 1 sensor 1)',SYS.emis,2,'The upstream O2 sensor stays at low voltage, reading lean.',['Faulty sensor','Exhaust leak before the sensor','Real lean condition','Shorted wire'],['Check for exhaust leaks','Check fuel trims','Replace the sensor']);
D('P0132','O2 sensor circuit high voltage (Bank 1 sensor 1)',SYS.emis,2,'The upstream O2 sensor stays at high voltage, reading rich.',['Faulty sensor','Signal shorted to voltage','Contaminated sensor (coolant or oil burning)'],['Inspect wiring','Check for coolant/oil consumption','Replace the sensor']);
D('P0133','O2 sensor circuit slow response (Bank 1 sensor 1)',SYS.emis,1,'The upstream O2 sensor switches between rich and lean too slowly. It is usually just old.',['Aged or contaminated O2 sensor','Exhaust leak','Vacuum leak'],['Check for exhaust leaks','Replace the upstream O2 sensor (often due after 150 000 km)']);
