D('P0193','Fuel rail pressure sensor circuit high',SYS.fuel,2,'The rail pressure sensor voltage is too high.',['Faulty sensor','Signal shorted to voltage','Open ground'],['Inspect wiring','Replace sensor']);
D('P0217','Engine over-temperature condition',SYS.fuel,3,'The engine has overheated. This can warp the cylinder head and blow the head gasket.',['Low coolant / leak','Cooling fan not working','Failed thermostat (stuck closed)','Failed water pump','Blocked radiator'],['Stop the engine and let it cool before opening the cap','Check coolant level and look for leaks','Check the cooling fans run when hot','Pressure-test the cooling system','Check for exhaust gas in coolant (head gasket test)'],'Stop driving. Overheating can destroy the engine within minutes.');
D('P0219','Engine overspeed condition',SYS.fuel,2,'The engine exceeded its maximum rpm.',['Over-revving during a downshift','Wheel spin','Faulty crank sensor signal'],['Check driving history','Inspect for engine damage if repeated','Test crank sensor']);
