const RANGES = [
  [/^P0[0-2]/, SYS.fuel], [/^P03/, SYS.ign], [/^P04/, SYS.emis], [/^P05/, SYS.idle], [/^P06/, SYS.ecm],
  [/^P0[7-9]/, SYS.trans], [/^P0A/, 'Hybrid / EV propulsion'], [/^P2/, 'Powertrain (extended generic)'], [/^P3/, 'Powertrain (extended)'],
  [/^P1/, 'Powertrain (manufacturer-specific)'], [/^C/, SYS.chas], [/^B/, SYS.body], [/^U/, SYS.net]
];

export const DTC_RE = /^[PCBU][0-3][0-9A-F]{3}$/;

export function lookup(code){
  if (DB[code]) return Object.assign({known:true, oem:false}, DB[code]);
  let sys = 'Unknown system';
  for (const [re, s] of RANGES) if (re.test(code)) { sys = s; break; }
  const oem = /^[PCBU][13]/.test(code) || (/^[CBU]/.test(code) && code[1]!=='0');
  const L = code[0];
  const sev = /^B00/.test(code) ? 3 : 2;
  const what = {P:'engine or transmission (powertrain)',C:'chassis (brakes, ABS, steering, suspension)',B:'body (airbags, seat belts, lighting, comfort)',U:'communication between the car’s computers'}[L] || 'vehicle';
  return {known:false, oem, code, sev, sys,
    title: oem ? 'Manufacturer-specific code' : 'Generic code — not in the built-in library',
    mean: `This code relates to the ${what}. ${oem ? 'Its exact meaning depends on the vehicle make, so look it up in that manufacturer’s service information.' : 'Look up the exact SAE J2012 definition for this code.'}${/^B00/.test(code)?' Codes beginning B00 usually relate to the airbag (SRS) system.':''}`,
    causes:['A sensor, actuator or wiring fault in the system named above','Check for other codes in the same system that point to a common cause'],
    fixes:['Look up the code in the manufacturer’s service information for this exact vehicle','Inspect related wiring and connectors','Repair, clear the code and road-test to confirm'],
    drive: /^B00/.test(code) ? 'An airbag fault may stop airbags deploying in a crash. Have it inspected promptly.' : null};
}

export const DRIVE = {3:'Repair before further driving where possible. Continued driving risks engine, catalytic converter or safety-system damage.',2:'Usually safe to drive short-term. Book a repair soon; performance, fuel use or emissions may suffer.',1:'Low urgency. Monitor it and repair at the next service.'};
export const SEVNAME = {3:'Critical',2:'Repair soon',1:'Low priority'};

/* Tips that only make sense when certain codes appear together. */
export function correlations(codes){
  const has = c => codes.includes(c), any = re => codes.some(c => re.test(c));
  const out = [];
  if (has('P0171') && has('P0174')) out.push('Both banks are lean (P0171 + P0174). Look for a cause shared by the whole engine: a vacuum leak, dirty MAF sensor or low fuel pressure, rather than a single sensor.');
  if (has('P0172') && has('P0175')) out.push('Both banks are rich (P0172 + P0175). Suspect a shared cause such as high fuel pressure, a faulty MAF or a clogged air filter.');
  if (any(/^P030\d|^P031[0-2]/) && any(/^P017[14]|^P2187/)) out.push('Misfire with lean codes: fix the lean condition first. A lean mixture is a common cause of misfires.');
  if (any(/^P04[23]0/) && any(/^P030\d|^P031[0-2]|^P017[1245]/)) out.push('Catalyst efficiency code alongside misfire or fuel-trim codes: repair those first and re-test. Misfires and rich running damage converters, and replacing the converter before fixing them will waste money.');
  if (any(/^P035\d/) && any(/^P030\d/)) out.push('Ignition coil circuit code with a misfire: the coil is the most likely cause of that misfire.');
  if (any(/^P020\d/) && any(/^P030\d/)) out.push('Injector circuit code with a misfire: check that injector before replacing plugs or coils.');
  if (has('P0016') && any(/^P001[0-4]|^P034[01]/)) out.push('Several timing-related codes together: check the timing chain/belt for stretch or a jumped tooth before replacing sensors.');
  if (codes.filter(c=>/^U0/.test(c)).length >= 2) out.push('Several "lost communication" codes: check battery voltage, main grounds and the network wiring before replacing any module.');
  if (has('P0562') || has('P0560')) out.push('Low system voltage can set unrelated sensor and communication codes. Fix the charging system first, clear all codes, then re-scan.');
  if (has('P0700')) out.push('P0700 is a pointer only. The real fault is stored in the transmission module; scan it separately.');
  if (has('P0299') && has('P2463')) out.push('Underboost with a soot-loaded DPF: a blocked DPF restricts the exhaust and reduces boost. Deal with the DPF before replacing turbo parts.');
  return out;
}
